create_order_preview.code:
const response = await client.orderPreviews.createOrderPreview({
    customer_id: 512,
    delivery_type: 'shipping',
    products: [{product_id: 101, quantity: 2}],
});
const preview = response.map.order;
console.log(preview.session.session_id, preview.session.expires_at);
console.log(preview.totals.sub_total, preview.totals.shipping_cost, preview.totals.grand_total);

get_order_preview.code:
const response = await client.orderPreviews.getOrderPreview('PRV-3f2a9c41b7d80e65');
const preview = response.map.order;
console.log(preview.session.status, preview.items.length, preview.totals.grand_total);

confirm_order_preview.code:
const response = await client.orderPreviews.confirmOrderPreview('PRV-3f2a9c41b7d80e65', {
    send_email: false,
    transaction_no: 'TXN-ORDER-0001',
    payment: {
        amount: 10.0,
        payment_status: 'success',
        payment_method: 'manual',
        transaction_reference: 'REF-0001',
        transaction_date: '2026-11-05T06:12:00Z',
    },
});
const order = response.map.order;
console.log(order.order_id, order.order_no, order.order_status, order.payment_status);

